/**
 * Make commands dispatched on the child editor propagate to the parent editor
 * after the child's own command handlers have run.
 *
 * When the parent editor is not currently updating, Lexical's built-in
 * propagation (via `_parentEditor`) already runs the child's handlers followed
 * by the parent's, synchronously, reporting the child as the dispatching editor
 * ($getEditor still returns the parent inside the parent's handlers). In that
 * case dispatchCommand behaves as normal and we simply delegate to it.
 *
 * When the parent editor is in the middle of an update, propagating to it
 * synchronously would trigger an early commit and could corrupt its node map,
 * so the built-in propagation intentionally stops at the child. Here we run the
 * child's own handlers immediately (within the parent's update) and defer the
 * propagation to the parent until its update has finished.
 */
function registerCommandPropagation(editor: LexicalEditor): () => void {
  const originalDispatchCommand = editor.dispatchCommand.bind(editor);
  editor.dispatchCommand = function nestedDispatchCommand<
    TCommand extends LexicalCommand<unknown>,
  >(type: TCommand, payload: CommandPayloadType<TCommand>): boolean {
    const parentEditor = editor._parentEditor;
    if (!parentEditor || !parentEditor._updating) {
      // No parent, or the parent is idle: the built-in `_parentEditor`
      // propagation already dispatches to the child and then the parent
      // synchronously, returning true if any handler (including a parent
      // handler) returned true.
      return originalDispatchCommand(type, payload);
    }
    // The parent is mid-update. Detach the parent temporarily so that the
    // built-in propagation only runs the child's own command handlers, and
    // capture the child-side result to return synchronously.
    const savedParentEditor = editor._parentEditor;
    editor._parentEditor = null;
    let childResult: boolean;
    try {
      childResult = originalDispatchCommand(type, payload);
    } finally {
      editor._parentEditor = savedParentEditor;
    }
    // Defer the propagation to the parent until after its active update
    // completes. Re-dispatching from the child (with its own handlers
    // temporarily removed so they don't run a second time) ensures the
    // parent's handlers receive the child as their editor argument.
    parentEditor._deferred.push(() => {
      const childCommands = editor._commands.get(type);
      if (childCommands !== undefined) {
        editor._commands.delete(type);
      }
      try {
        originalDispatchCommand(type, payload);
      } finally {
        if (childCommands !== undefined) {
          editor._commands.set(type, childCommands);
        }
      }
    });
    return childResult;
